package com.badimps.personaltrainer;

import android.app.*;import android.content.*;import android.os.*;
import androidx.core.app.NotificationCompat;
import androidx.health.services.client.*;import androidx.health.services.client.data.*;
import com.google.android.gms.wearable.*;import com.google.common.util.concurrent.*;
import java.util.*;import java.util.concurrent.Executor;

/** Owns Health Services for standalone walk/run/cycle recording and phone handoff. */
public final class WearHealthExerciseService extends android.app.Service implements ExerciseUpdateCallback {
    public static final String START="health.start",PAUSE="health.pause",RESUME="health.resume",END="health.end",UPDATE="health.update";
    private static final String CHANNEL="endurance_tracking", SUMMARY="/health/session/summary",GUIDED_LIVE="/health/workout/live",GUIDED_SUMMARY="/health/workout/summary";
    private ExerciseClient client;private Executor executor;private String mode="walking",sessionId="";private boolean paused;private long duration,sessionTimestamp;private double distance,calories,speed,elevation,heart;private final ArrayList<LocationData> route=new ArrayList<>();
    @Override public void onCreate(){super.onCreate();executor=getMainExecutor();client=HealthServices.getClient(this).getExerciseClient();client.setUpdateCallback(executor,this);NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel(CHANNEL,"Endurance tracking",NotificationManager.IMPORTANCE_LOW));}
    @Override public int onStartCommand(Intent i,int f,int id){if(i==null)return START_STICKY;String a=i.getAction();if(START.equals(a)){mode=i.getStringExtra("mode");if(mode==null)mode="walking";sessionId=i.getStringExtra("session_id");if(sessionId==null)sessionId="";sessionTimestamp=i.getLongExtra("started",System.currentTimeMillis());int serviceType=android.content.pm.ServiceInfo.FOREGROUND_SERVICE_TYPE_HEALTH;if(!"guided".equals(mode))serviceType|=android.content.pm.ServiceInfo.FOREGROUND_SERVICE_TYPE_LOCATION;startForeground(882,notification("Preparing sensors"),serviceType);WearHealthSessionStore.begin(this,mode);startWithCapabilities();}else if(PAUSE.equals(a)){client.pauseExerciseAsync();paused=true;persist();}else if(RESUME.equals(a)){client.resumeExerciseAsync();paused=false;persist();}else if(END.equals(a)){finishAndSync();}return START_STICKY;}
    private void startWithCapabilities(){ListenableFuture<ExerciseCapabilities> future=client.getCapabilitiesAsync();Futures.addCallback(future,new FutureCallback<>(){public void onSuccess(ExerciseCapabilities all){ExerciseType type=type();ExerciseTypeCapabilities caps=all.getExerciseTypeCapabilities(type);if(caps==null){stopSelf();return;}Set<DataType<?,?>> wanted=new HashSet<>(Arrays.asList(DataType.HEART_RATE_BPM,DataType.HEART_RATE_BPM_STATS,DataType.CALORIES_TOTAL,DataType.DISTANCE_TOTAL,DataType.SPEED,DataType.SPEED_STATS,DataType.ELEVATION_GAIN_TOTAL,DataType.LOCATION,DataType.ACTIVE_EXERCISE_DURATION_TOTAL));wanted.retainAll(caps.getSupportedDataTypes());ExerciseConfig config=new ExerciseConfig.Builder(type).setDataTypes(wanted).setIsGpsEnabled(wanted.contains(DataType.LOCATION)).setIsAutoPauseAndResumeEnabled(caps.getSupportsAutoPauseAndResume()).build();Futures.addCallback(client.startExerciseAsync(config),new FutureCallback<>(){public void onSuccess(Void v){updateNotification("Tracking "+mode);persist();}public void onFailure(Throwable t){getSharedPreferences("watch_health_bridge",MODE_PRIVATE).edit().putBoolean("guided",false).apply();updateNotification("Unable to start sensors");}},executor);}public void onFailure(Throwable t){getSharedPreferences("watch_health_bridge",MODE_PRIVATE).edit().putBoolean("guided",false).apply();updateNotification("Health Services unavailable");}},executor);}
    private ExerciseType type(){return"guided".equals(mode)?ExerciseType.STRENGTH_TRAINING:"running".equals(mode)?ExerciseType.RUNNING:"cycling".equals(mode)?ExerciseType.BIKING:ExerciseType.WALKING;}
    @Override public void onRegistered(){} public void onRegistrationFailed(Throwable t){updateNotification("Sensor connection failed");}
    @Override public void onExerciseUpdateReceived(ExerciseUpdate u){DataPointContainer m=u.getLatestMetrics();heart=latestSample(m,DataType.HEART_RATE_BPM,heart);speed=latestSample(m,DataType.SPEED,speed);distance=total(m,DataType.DISTANCE_TOTAL,distance);calories=total(m,DataType.CALORIES_TOTAL,calories);elevation=total(m,DataType.ELEVATION_GAIN_TOTAL,elevation);duration=(long)total(m,DataType.ACTIVE_EXERCISE_DURATION_TOTAL,duration);for(SampleDataPoint<LocationData> p:m.getData(DataType.LOCATION)){LocationData l=p.getValue();if(route.isEmpty()||farEnough(route.get(route.size()-1),l))route.add(l);}paused=u.getExerciseStateInfo().getState().isPaused();persist();}
    private static boolean farEnough(LocationData a,LocationData b){return Math.abs(a.getLatitude()-b.getLatitude())+Math.abs(a.getLongitude()-b.getLongitude())>.00001;}
    private static double latestSample(DataPointContainer c,DeltaDataType<Double,SampleDataPoint<Double>> t,double fallback){List<SampleDataPoint<Double>> v=c.getData(t);return v.isEmpty()?fallback:v.get(v.size()-1).getValue();}
    private static double total(DataPointContainer c,AggregateDataType<? extends Number,? extends DataPoint<? extends Number>> t,double fallback){DataPoint<? extends Number> p=c.getData((AggregateDataType)t);if(p instanceof CumulativeDataPoint)return((CumulativeDataPoint<? extends Number>)p).getTotal().doubleValue();return fallback;}
    private void persist(){String r=encodeRoute();WearHealthSessionStore.update(this,paused,duration,distance,calories,speed,elevation,heart,r);if("guided".equals(mode))publishHealth(GUIDED_LIVE,false);sendBroadcast(new Intent(UPDATE).setPackage(getPackageName()));updateNotification("guided".equals(mode)?String.format(Locale.US,"%.0f bpm • %.0f kcal",heart,calories):String.format(Locale.US,"%.2f km • %.0f bpm • %.0f kcal",distance/1000,heart,calories));}
    private String encodeRoute(){StringBuilder b=new StringBuilder();int start=Math.max(0,route.size()-350);for(int x=start;x<route.size();x++){if(b.length()>0)b.append(';');LocationData l=route.get(x);b.append(String.format(Locale.US,"%.6f,%.6f",l.getLatitude(),l.getLongitude()));}return b.toString();}
    private void finishAndSync(){Futures.addCallback(client.endExerciseAsync(),new FutureCallback<>(){public void onSuccess(Void v){sync();}public void onFailure(Throwable t){sync();}},executor);}
    private void sync(){publishHealth("guided".equals(mode)?GUIDED_SUMMARY:SUMMARY,true);WearHealthSessionStore.finish(this);sendBroadcast(new Intent(UPDATE).setPackage(getPackageName()));stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}
    private void publishHealth(String path,boolean finalValue){WearHealthSessionStore.State s=WearHealthSessionStore.load(this);PutDataMapRequest request=PutDataMapRequest.create(path);DataMap m=request.getDataMap();m.putString("session_id",sessionId);m.putLong("timestamp",sessionTimestamp>0?sessionTimestamp:s.startedAt);m.putString("mode",s.mode);m.putLong("active_millis",s.activeMillis);m.putFloat("distance_meters",(float)s.distance);m.putFloat("calories",(float)s.calories);m.putFloat("heart_rate",(float)s.heartRate);m.putFloat("speed",(float)s.speed);m.putFloat("elevation",(float)s.elevation);m.putString("route",s.route);m.putBoolean("final",finalValue);m.putLong("nonce",System.nanoTime());Wearable.getDataClient(this).putDataItem(request.asPutDataRequest().setUrgent());}
    private Notification notification(String line){Intent open=new Intent(this,WearHealthActivity.class);PendingIntent pi=PendingIntent.getActivity(this,3,open,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);return new NotificationCompat.Builder(this,CHANNEL).setSmallIcon(android.R.drawable.ic_media_play).setContentTitle("Coach endurance active").setContentText(line).setOngoing(true).setContentIntent(pi).build();}
    private void updateNotification(String line){getSystemService(NotificationManager.class).notify(882,notification(line));}
    @Override public void onLapSummaryReceived(ExerciseLapSummary s){} @Override public void onAvailabilityChanged(DataType<?,?> t,Availability a){} @Override public android.os.IBinder onBind(Intent i){return null;}
}
